import {loadLiveCatalog,loadLibrary,catalogEntry} from './live-catalog.js';
import {apiRequest} from './api-client.js';
import {initializeAuth,openAccountControls,currentAccount} from './account-controls.js';
import {recommend,qualityFor,resumeAt} from './core.js';
import {catalog,featuredIds} from './catalog.js';
import {openVideoStudio} from './video-studio.js';
import {openRecommendationControls} from './recommendation-controls.js';
import {hasSession,loadRecommendationLayout,saveRemoteProgress,saveRemoteReaction} from './api-client.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const titleById=id=>catalog.find(f=>f.id===id);
const previewCatalog=[...catalog];
const knownIds=new Set(catalog.map(f=>f.id));
const icons=()=>window.lucide?.createIcons();
let raw={};try{raw=JSON.parse(localStorage.getItem('aether-v1'))||{};}catch{/* Browsing remains available when storage is unavailable. */}
let state={...raw,likes:Array.isArray(raw.likes)?raw.likes.filter(id=>knownIds.has(id)):[],saved:Array.isArray(raw.saved)?raw.saved.filter(id=>knownIds.has(id)):[],progress:raw.progress&&typeof raw.progress==='object'?raw.progress:{},drafts:Array.isArray(raw.drafts)?raw.drafts:[]};
let serverLayout=null,layoutRequest=0;
const html=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='discover',genre='All',onlyOriginals=false,featureId='signal',mediaCleanup=null,toastTimer;
/** Persist only local preview data; never store tokens or payment credentials in this object. */
function persist(){if(hasSession())return;try{localStorage.setItem('aether-v1',JSON.stringify(state));}catch{toast('Storage is unavailable. Your changes will last for this visit.');}}
/** Announce status without stealing focus. */
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
/** Stop the current media and flush progress before replacing or closing its dialog. */
function cleanupMedia(){if(mediaCleanup){const cleanup=mediaCleanup;mediaCleanup=null;cleanup();}}
/** Update a native accessible dialog. Markup comes only from trusted catalog data. */
function modal(html,label='Aether details'){cleanupMedia();$('#modalBody').innerHTML=html;$('#modal').setAttribute('aria-label',label);if(!$('#modal').open)$('#modal').showModal();icons();}
function closeModal(){cleanupMedia();$('#modal').close();}
$('.close').onclick=closeModal;$('#modal').addEventListener('close',cleanupMedia);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
/** Use genre affinity rather than displaying fabricated viewing metrics. */
function recommendationReason(f){return state.likes.some(id=>titleById(id)?.genre===f.genre)?'Because you like '+f.genre.toLowerCase():'An Aether editorial pick';}
/** Synchronize every collection control without re-rendering scroll positions. */
function syncCollection(){if(!catalog.length)return;const count=state.saved.length;$('#count').textContent=count;$$('[data-save-id]').forEach(b=>{const f=titleById(b.dataset.saveId),saved=state.saved.includes(f.id);b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',`${saved?'Remove':'Add'} ${html(f.title)} ${saved?'from':'to'} my list`);b.innerHTML=icon(saved?'check':'plus');});const f=titleById(featureId)||catalog[0],saved=state.saved.includes(featureId);$('#heroSave').classList.toggle('saved',saved);$('#heroSave').setAttribute('aria-pressed',String(saved));$('#heroSave').setAttribute('aria-label',`${saved?'Remove':'Add'} ${html(f.title)} ${saved?'from':'to'} my list`);$('#heroSave').innerHTML=icon(saved?'check':'plus');icons();}
function toggleSaved(id){const saved=state.saved.includes(id);state.saved=saved?state.saved.filter(x=>x!==id):[...state.saved,id];persist();void saveRemoteReaction(id,{liked:state.likes.includes(id),saved:state.saved.includes(id)}).catch(()=>toast('Saved locally; account sync is unavailable.'));syncCollection();if(view==='list')render();toast(saved?'Removed from my list':'Added to my list');}
/** Build a fully keyboard-operable card; detail and collection actions remain separate. */
function card(f,{progress=false,rank=0,portrait=false}={}){const el=document.createElement('article');el.className='film-card';const position=state.progress[f.id],fraction=Number.isFinite(position?.seconds)&&position.duration>0?Math.min(100,position.seconds/position.duration*100):0;const secondsLeft=position?.duration-position?.seconds;el.innerHTML=`${rank?`<span class="rank" aria-hidden="true">${rank}</span>`:''}<button class="poster" aria-label="${progress?'Resume':'Explore'} ${html(f.title)}"><img src="${html(portrait?(f.poster||f.image):f.image)}" alt="${html(f.alt)}" loading="lazy"><span class="card-topline"><span class="card-original">${f.original?'A':''}</span><span class="badge">${html(f.tag)}</span></span><span class="poster-title"></span><span class="hover-play">${icon('play')}</span>${progress?`<span class="time-left">${Math.max(1,Math.ceil(secondsLeft/60))} min left</span><span class="progress"><span style="display:block;height:100%;width:${fraction}%;background:var(--lime)"></span></span>`:''}</button><div class="card-info"><div style="min-width:0"><h3></h3><p class="card-meta"><span>${html(f.year)}</span><span>·</span><span>${html(f.genre)}</span><span>·</span><span>${progress?'Resume':f.duration}</span></p></div><button class="save" data-save-id="${f.id}" aria-label="Add ${html(f.title)} to my list" aria-pressed="false">${icon('plus')}</button></div>`;el.querySelector('.poster-title').textContent=f.title;el.querySelector('h3').textContent=f.title;el.querySelector('.poster').onclick=()=>progress?play(f):details(f);el.querySelector('.save').onclick=()=>toggleSaved(f.id);return el;}
/** Build a scrollable content shelf with accessible left/right controls and measured scroll steps. */
function shelf({id,title,subtitle='',tag='',films,portrait=false,ranked=false,progress=false,filter=null}){if(!films.length)return null;const section=document.createElement('section');section.className='content-row';section.setAttribute('aria-label',title);section.innerHTML=`<div class="row-heading"><div><div class="heading-group"><h2></h2>${tag?`<span class="row-eyebrow">${tag}</span>`:''}</div>${subtitle?'<p class="row-description"></p>':''}</div><div class="row-controls">${filter?`<button class="view-all">View all ${icon('arrow-up-right')}</button>`:''}<button aria-label="Scroll ${html(title)} left">${icon('chevron-left')}</button><button aria-label="Scroll ${html(title)} right">${icon('chevron-right')}</button></div></div><div id="${id}" class="rail ${portrait?'poster-rail':''} ${ranked?'ranked-rail':''}" tabindex="0" aria-label="${html(title)} titles"></div>`;section.querySelector('h2').textContent=title;if(subtitle)section.querySelector('.row-description').textContent=subtitle;const rail=section.querySelector('.rail');rail.append(...films.map((f,i)=>card(f,{portrait,rank:ranked?i+1:0,progress})));const controls=section.querySelectorAll('.row-controls button:not(.view-all)');const update=()=>{controls[0].disabled=rail.scrollLeft<=2;controls[1].disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-3;};controls[0].onclick=()=>rail.scrollBy({left:-rail.clientWidth*.85,behavior:motion()});controls[1].onclick=()=>rail.scrollBy({left:rail.clientWidth*.85,behavior:motion()});rail.addEventListener('scroll',update,{passive:true});const observer=new ResizeObserver(update);observer.observe(rail);resizeObservers.push(observer);if(filter)section.querySelector('.view-all').onclick=()=>setBrowse(filter);return section;}
const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
/** Curated genre tiles provide a direct route into filtered catalog results. */
function genreSection(){const el=document.createElement('section');el.className='genres-row';el.innerHTML='<div class="row-heading"><h2>Find your kind of escape</h2></div><div class="genre-grid"></div>';const picks=[['Sci-Fi','Sci-Fi & fantasy','orbit'],['Thriller','Edge-of-your-seat','night'],['Drama','All the feels','coast'],['Adventure','Adventure awaits','wild'],['Documentary','Our extraordinary world','earth']];picks.forEach(([g,label,id])=>{const f=titleById(id)||catalog.find(x=>x.genre===g);if(!f)return;const b=document.createElement('button');b.className='genre-tile';b.innerHTML=`<img loading="lazy" src="${html(f.image)}" alt=""><span></span>${icon('arrow-up-right')}`;b.querySelector('span').textContent=label;b.onclick=()=>setBrowse({genre:g});el.querySelector('.genre-grid').append(b);});return el;}
let resizeObservers=[];
/** Render personalized home shelves, filtered catalog or saved list. Never invent watch history. */
function render(){resizeObservers.forEach(observer=>observer.disconnect());resizeObservers=[];const q=$('#search').value.trim().toLowerCase(),home=view==='discover'&&genre==='All'&&!q&&!onlyOriginals;const ranked=recommend(catalog,state.likes,state.progress);const films=ranked.filter(f=>(genre==='All'||f.genre===genre)&&(!q||`${html(f.title)} ${html(f.genre)}`.toLowerCase().includes(q))&&(!onlyOriginals||f.original)&&(view==='discover'||view==='all'||(view==='list'?state.saved.includes(f.id):f.type===view)));$('#catalogRows').hidden=!home;$('#searchResults').hidden=home;$('#resultsHeading').hidden=home;$('.editorial-banner').hidden=!home;$('.membership-strip').hidden=!home;$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===(view==='all'?'discover':view));if(b.dataset.view===(view==='all'?'discover':view))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$$('[data-genre]').forEach(b=>{b.classList.toggle('selected',b.dataset.genre===genre);b.setAttribute('aria-pressed',String(b.dataset.genre===genre));});if(home){const rows=$('#catalogRows');rows.replaceChildren();const continued=catalog.filter(f=>Number.isFinite(state.progress[f.id]?.seconds)&&state.progress[f.id].seconds>0&&!state.progress[f.id].completed);let rowSpecs=[{id:'continueRail',title:'Continue watching',subtitle:'A good story is worth coming back to.',films:continued,progress:true},{id:'pickedRail',title:state.likes.length?'Picked for your taste':'Your next obsession',tag:'HANDPICKED',films:ranked.slice(0,8),filter:{view:'all'}},{id:'originalRail',title:'Only on Aether',subtitle:'Distinctive voices. Unforgettable worlds.',tag:'ORIGINALS',films:catalog.filter(f=>f.original),portrait:true,filter:{view:'all',originals:true}},{id:'topRail',title:'The Aether top 10',subtitle:'Ten stories at the top of our editorial list.',films:[...catalog].sort((a,b)=>b.rating-a.rating).slice(0,10),ranked:true},{id:'seriesRail',title:'One more episode',subtitle:'Discover your next series.',films:catalog.filter(f=>f.type==='series'),filter:{view:'series'}},{id:'natureRail',title:'Extraordinary by nature',films:catalog.filter(f=>['Adventure','Documentary'].includes(f.genre)),filter:{genre:'Documentary'}}];if(serverLayout?.rows?.length){const remote=serverLayout.rows.slice().sort((a,b)=>a.position-b.position).map(row=>({id:'remote_'+row.position,title:row.title,subtitle:row.reason||'Personalized from your viewing activity',films:row.items.slice().sort((a,b)=>a.position-b.position).map(item=>titleById(item.title_id)).filter(Boolean),progress:row.id==='continue',portrait:row.id!=='continue'})).filter(row=>row.films.length);if(remote.length)rowSpecs=remote;}rowSpecs.forEach((spec,i)=>{const row=shelf(spec);if(row)rows.append(row);if(i===2)rows.append(genreSection());});}else{$('#sectionHeading').textContent=q?`Results for “${$('#search').value.trim()}”`:view==='list'?'My list':onlyOriginals?'Only on Aether':view==='all'?'Explore all stories':genre!=='All'?`${genre==='Sci-Fi'?'Sci-Fi & fantasy':genre} stories`:view==='series'?'Series worth staying in for':'Make it a movie night';$('#resultCount').textContent=`${films.length} ${films.length===1?'story':'stories'} to explore`;$('#cards').replaceChildren(...films.map(f=>card(f,{portrait:true})));$('#empty').hidden=films.length>0;}syncCollection();icons();}
/** Switch catalog context and bring the result set into view. */
function setBrowse({view:nextView='discover',genre:nextGenre='All',originals=false}={}){if(location.hash==='#account'){location.hash='';$('#catalogPage').hidden=false;$('#accountPage').hidden=true;}view=nextView;genre=nextGenre;onlyOriginals=originals;$('#search').value='';render();$('#browse').scrollIntoView({behavior:motion(),block:'start'});}
/** Switch among featured films explicitly; avoid distracting autoplay or auto-rotation. */
function feature(id){const f=titleById(id);if(!f)return;featureId=id;$('#heroImage').src=f.image;$('#heroImage').alt=f.alt;$('#heroTitle').textContent=f.title.toUpperCase();$('#heroKicker').textContent=f.kicker||'DISCOVER YOUR NEXT GREAT STORY.';$('#heroDescription').textContent=f.description;$('#heroMeta').innerHTML=`<span class="match">Aether pick</span><span>${html(f.year)}</span><span class="rating">${html(f.age)}</span><span>${html(f.duration)}</span><span class="quality-label">HD</span><span>${html(f.genre)}${id==='signal'?' · Mystery':''}</span>`;$$('[data-feature]').forEach(b=>{b.classList.toggle('active',b.dataset.feature===id);b.setAttribute('aria-pressed',String(b.dataset.feature===id));});$('#heroTitle').style.fontSize=f.title.length>14?'clamp(42px,4.5vw,68px)':'';syncCollection();}
/** Present original artwork, recommendation explanation and collection/like controls. */
function details(f){if(f.live)return liveDetails(f);modal(`<div class="detail-art"><img src="${html(f.image)}" alt="${html(f.alt)}"><div><p class="eyebrow">${f.original?'AETHER ORIGINAL':f.tag}</p><h2>${html(f.title)}</h2></div></div><div class="detail-body"><div class="row-actions"><button class="button button-primary" id="watch">${icon('play')} ${state.progress[f.id]?.seconds?'Resume sample':'Watch sample'}</button><button class="circle-button" data-save-id="${f.id}" aria-label="Add ${html(f.title)} to my list">${icon('plus')}</button><button class="circle-button" id="like" aria-label="${state.likes.includes(f.id)?'Unlike':'Like'} ${html(f.title)}" aria-pressed="${state.likes.includes(f.id)}">${icon('thumbs-up')}</button></div><div class="detail-meta"><span class="match">${recommendationReason(f)}</span><span>${html(f.year)}</span><span class="rating">${html(f.age)}</span><span>${html(f.duration)}</span><span>${html(f.genre)}</span></div><p class="detail-description">${f.description}</p><div class="detail-subinfo"><div><h3>The mood</h3><p>${{Thriller:'Atmospheric. Suspenseful. Impossible to look away.',Drama:'Intimate. Heartfelt. Beautifully human.',Adventure:'Breathtaking. Restless. Full of wonder.',Documentary:'Eye-opening. Immersive. Closer to the extraordinary.','Sci-Fi':'Otherworldly. Ambitious. A little mind-bending.'}[f.genre]}</p></div><div><h3>${f.type==='series'?'About the series':'About the film'}</h3><p>${html(f.duration)} · ${html(f.year)} · ${html(f.genre)}<br>Part of the fictional Aether preview collection.</p></div></div>${f.type==='series'?'<div class="state-panel"><h3>Episode preview</h3><p class="muted">The series catalog is a concept preview. The play action opens the public sample film; individual episodes are not available.</p></div>':''}<p class="detail-note">Original concept artwork and fictional programming. All play actions use Big Buck Bunny trailer (Blender Foundation, CC BY 3.0), not the illustrated title. Likes and progress stay on this device.</p></div>`,f.title+' — details');$('#watch').onclick=()=>play(f);$('#modalBody [data-save-id]').onclick=()=>toggleSaved(f.id);$('#like').classList.toggle('saved',state.likes.includes(f.id));$('#like').onclick=()=>{const liked=state.likes.includes(f.id);state.likes=liked?state.likes.filter(id=>id!==f.id):[...state.likes,f.id];persist();void saveRemoteReaction(f.id,{liked:state.likes.includes(f.id),saved:state.saved.includes(f.id)}).then(refreshRecommendations).catch(()=>toast('Liked locally; account sync is unavailable.'));$('#like').classList.toggle('saved',!liked);$('#like').setAttribute('aria-pressed',String(!liked));$('#like').setAttribute('aria-label',`${liked?'Like':'Unlike'} ${html(f.title)}`);render();toast(liked?'Like removed':'Liked. Your recommendations have been updated.');};syncCollection();}
/** Resume sample playback and preserve sound/time without inventing adaptive quality changes. */
function play(f){if(f.live)return livePlay(f);modal(`<div class="player-heading"><p class="eyebrow">NOW PLAYING · PUBLIC SAMPLE</p><h2>${html(f.title)}</h2></div><video controls playsinline preload="metadata" src="https://media.w3.org/2010/05/bunny/trailer.mp4"></video><div class="player-status"><p class="player-error" id="playerError" hidden>Unable to load the sample. Check your connection and try again.</p><p class="muted" id="quality"></p><p class="muted">Big Buck Bunny trailer · Blender Foundation · CC BY 3.0</p><p class="detail-note">This is a single MP4 sample. Quality switching requires the production HLS integration. Playback position, volume, mute and speed are saved on this device.</p></div>`,f.title+' — sample player');const v=$('video');v.volume=Number.isFinite(state.volume)?Math.max(0,Math.min(1,state.volume)):.7;v.muted=!!state.muted;v.playbackRate=Number.isFinite(state.rate)&&state.rate>=.25&&state.rate<=4?state.rate:1;v.addEventListener('loadedmetadata',()=>{v.currentTime=resumeAt(state.progress[f.id]?.seconds,v.duration);});v.addEventListener('error',()=>$('#playerError')?.removeAttribute('hidden'));let last=0,pendingProgress=Promise.resolve();const save=()=>{if(!Number.isFinite(v.duration)||v.duration<=0)return;state.progress[f.id]={seconds:v.currentTime,duration:v.duration,completed:v.currentTime/v.duration>.95};state.volume=v.volume;state.muted=v.muted;state.rate=v.playbackRate;persist();const checkpoint={position:v.currentTime,duration:v.duration,volume:v.volume,muted:v.muted};pendingProgress=pendingProgress.catch(()=>{}).then(()=>saveRemoteProgress(f.id,checkpoint));};v.addEventListener('timeupdate',()=>{if(Date.now()-last>5000){last=Date.now();save();}});['pause','ended','volumechange','ratechange'].forEach(event=>v.addEventListener(event,save));mediaCleanup=()=>{save();v.pause();v.removeAttribute('src');v.load();render();void pendingProgress.catch(()=>{}).then(refreshRecommendations);};const network=navigator.connection;$('#quality').textContent=`Network-aware startup suggestion: ${qualityFor(network?.downlink,network?.saveData)}p · Preview source: MP4`;}
/** Memberships come from server-owned Stripe prices; browser amounts never authorize a charge. */
async function plans(){
 modal('<div class="dialog-padding"><p class="eyebrow">YOUR MEMBERSHIP</p><h2>Choose your next chapter.</h2><p id="billingStatus" role="status">Loading membership options…</p><div id="billingPlans" class="plans"></div><div id="streamSessions"></div></div>','Aether memberships');
 const status=$('#billingStatus'),container=$('#billingPlans');
 try{
  if(!hasSession())throw new Error('Sign in through your profile to view membership options.');
  const data=await apiRequest('/api/billing');if(!container.isConnected)return;
  status.textContent=data.configured?`Membership: ${data.subscription.status||'none'}. Stream limits apply across your account.`:'Stripe is not configured on this deployment. No payment can be collected.';
  for(const plan of data.plans){const item=document.createElement('div');item.className='plan';const requestId=crypto.randomUUID();const money=new Intl.NumberFormat(undefined,{style:'currency',currency:plan.currency});const amount=money.format(plan.amount/10**money.resolvedOptions().maximumFractionDigits);item.innerHTML=`<h3>${html(plan.id)}</h3><strong>${html(amount)}</strong><p>Every ${plan.intervalCount} ${html(plan.interval)} · ${plan.streams} simultaneous streams</p><button class="button button-primary" type="button">Subscribe</button>`;
   const button=item.querySelector('button');button.onclick=async()=>{button.disabled=true;try{const result=await apiRequest('/api/checkout',{method:'POST',body:JSON.stringify({plan:plan.id,requestId})});const url=new URL(result.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw new Error('Invalid checkout address');location.assign(url.href);}catch(e){status.textContent=e.message;button.disabled=false;}};container.append(item);
  }
  if(data.configured&&data.subscription.status){const portal=document.createElement('button');portal.className='button button-secondary';portal.textContent='Manage subscription';portal.onclick=async()=>{try{const result=await apiRequest('/api/billing/portal',{method:'POST'});const u=new URL(result.url);if(u.protocol!=='https:'||u.hostname!=='billing.stripe.com')throw new Error('Invalid billing address');location.assign(u.href);}catch(e){status.textContent=e.message;}};container.append(portal);}
  const sessions=await apiRequest('/api/playback-sessions');if(!container.isConnected)return;
  for(const session of sessions){const row=document.createElement('p'),button=document.createElement('button');row.textContent=session.name+' ';button.textContent='Stop stream';button.onclick=async()=>{try{await apiRequest('/api/playback-sessions/'+session.id,{method:'DELETE'});row.remove();}catch(e){status.textContent=e.message;}};row.append(button);$('#streamSessions').append(row);}
 }catch(e){if(status.isConnected)status.textContent=e.message;}
}
/** Published films use protected HLS; a series lists real independently uploaded episodes. */
async function liveDetails(f){
 modal(`<div class="dialog-padding"><p class="eyebrow">${html(f.tag)}</p><h2>${html(f.title)}</h2><p>${html(f.description)}</p><div class="video-actions"><button class="button button-primary" id="liveWatch">${f.type==='series'?'Load episodes':'Watch film'}</button><button class="button button-secondary" id="liveSave">${state.saved.includes(f.id)?'Remove from list':'Save to list'}</button><button class="button button-secondary" id="liveLike">${state.likes.includes(f.id)?'Unlike':'Like'}</button></div><div id="episodeList" role="status"></div></div>`,f.title);
 $('#liveSave').onclick=()=>{toggleSaved(f.id);$('#liveSave').textContent=state.saved.includes(f.id)?'Remove from list':'Save to list';};
 $('#liveLike').onclick=async()=>{const liked=state.likes.includes(f.id);try{await saveRemoteReaction(f.id,{liked:!liked,saved:state.saved.includes(f.id)});state.likes=liked?state.likes.filter(x=>x!==f.id):[...state.likes,f.id];$('#liveLike').textContent=liked?'Like':'Unlike';void refreshRecommendations();}catch(e){toast(e.message);}};
 const watch=$('#liveWatch');watch.onclick=async()=>{if(f.type!=='series')return livePlay(f);watch.disabled=true;const list=$('#episodeList');try{const episodes=await apiRequest('/api/catalog/'+f.id+'/episodes');if(!list.isConnected)return;list.replaceChildren();for(const episode of episodes){const b=document.createElement('button');b.className='button button-secondary';b.textContent=`S${episode.season_number} E${episode.episode_number} · ${episode.name}`;b.onclick=()=>livePlay(catalogEntry(episode));list.append(b);}if(!episodes.length)list.textContent='No published episodes are available.';}catch(e){if(list.isConnected)list.textContent=e.message;}finally{watch.disabled=false;}};
 if(f.type==='series')void watch.click();
}
function livePlay(f){
 modal(`<div class="player-heading"><p class="eyebrow">NOW PLAYING</p><h2>${html(f.title)}</h2></div><video controls playsinline preload="metadata"></video><div class="player-status"><p id="adaptiveStatus" role="status">Checking membership and available streams…</p></div>`,f.title+' — player');
 const video=$('video'),status=$('#adaptiveStatus');let closed=false,cleanup=null;
 mediaCleanup=()=>{closed=true;cleanup?.();};
 void import('./adaptive-player.js').then(module=>{if(closed)return;cleanup=module.mountAdaptivePlayer({video,titleId:f.id,progress:state.progress[f.id],status,onProgress:p=>{state.progress[f.id]={seconds:p.position,duration:p.duration,volume:p.volume,muted:p.muted,completed:p.position/p.duration>=.95};}});}).catch(()=>{if(!closed)status.textContent='The adaptive player could not load. Try reopening the video.';});
}
/** Device-only studio preview; no client control grants a production admin role. */
function admin(){void openVideoStudio({modal,toast,onCleanup:fn=>{mediaCleanup=fn;}});}
function accountRoute(){const active=location.hash==='#account';$('#catalogPage').hidden=active;$('#accountPage').hidden=!active;if(!active){$('#accountPage').replaceChildren();document.title='AETHER — Beyond the ordinary.';return;}closeModal();$('#accountPage').innerHTML='<div class="account-page-heading"><button class="button button-secondary" id="accountBack">Back to browsing</button><p class="eyebrow">YOUR AETHER</p><h1>Profile & account</h1></div><div id="accountPageBody"></div>';$('#accountBack').onclick=()=>{location.hash='';};const root=$('#accountPageBody');void openAccountControls({modal:markup=>{if(root.isConnected)root.innerHTML=markup;},toast,onMembership:plans,isActive:()=>root.isConnected});document.title='Profile & account — Aether';$('#accountPage').focus({preventScroll:true});window.scrollTo({top:0});}
function profile(){if(location.hash==='#account')accountRoute();else location.hash='account';}
window.addEventListener('hashchange',accountRoute);
function updateAccountLabel(){const account=currentAccount(),button=$('#profile');button.textContent=account?`${account.name||'Account'} · ${account.role==='admin'?'Admin':'Signed in'}`:'Sign in';button.setAttribute('aria-label',account?`Signed in as ${account.email||account.name}. Open account`:'Sign in or create an account');button.title=account?.email||'You are signed out';}
window.addEventListener('aether:session-ready',updateAccountLabel);
window.addEventListener('aether:session-cleared',updateAccountLabel);
updateAccountLabel();

$$('[data-view]').forEach(b=>b.onclick=()=>setBrowse({view:b.dataset.view}));$$('[data-genre]').forEach(b=>b.onclick=()=>setBrowse({view,genre:b.dataset.genre}));$$('[data-feature]').forEach(b=>b.onclick=()=>feature(b.dataset.feature));$('#search').oninput=render;$('#searchToggle').onclick=()=>{$('#browse').scrollIntoView({behavior:motion()});$('#search').focus({preventScroll:true});};$('#heroPlay').onclick=()=>play(titleById(featureId));$('#heroDetails').onclick=()=>details(titleById(featureId));$('#heroSave').onclick=()=>toggleSaved(featureId);$('#plans').onclick=plans;$('#manifestoPlan').onclick=plans;$('#collectionExplore').onclick=()=>setBrowse({genre:'Adventure'});$('#admin').onclick=admin;$('#profile').onclick=profile;$('#resetFilters').onclick=()=>setBrowse();$$('.brand').forEach(a=>a.onclick=e=>{e.preventDefault();if(location.hash==='#account')location.hash='';view='discover';genre='All';onlyOriginals=false;$('#search').value='';render();window.scrollTo({top:0,behavior:motion()});});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#searchToggle').click();}});feature('signal');render();

window.addEventListener('scroll',()=>$('.site-header').classList.toggle('scrolled',window.scrollY>45),{passive:true});

/** Apply positions from the authenticated Python-backed plan; no request is sent before account integration. */
async function refreshRecommendations(){if(!hasSession())return;const request=++layoutRequest;try{const layout=await loadRecommendationLayout();if(request!==layoutRequest)return;serverLayout=layout;if(layout?.hero&&titleById(layout.hero))feature(layout.hero);if(!$('#modal').open)render();}catch{/* Existing editorial/browser ranking keeps discovery usable. */}}
let loadedProfile=null;
async function hydrateAccount(){if(!hasSession())return;try{
 const live=await loadLiveCatalog(),library=await loadLibrary();if(!hasSession())return;
 catalog.splice(0,catalog.length,...live);knownIds.clear();live.forEach(f=>knownIds.add(f.id));state={...state,...library};serverLayout=null;
 $('.hero').hidden=!live.length;$('.featured-switcher').hidden=true;$('.hero-credit').textContent='Published catalog · Adaptive streaming';$('.original-label').textContent='AETHER CATALOG';$('#heroPlay').textContent='Watch';
 if(live.length)feature(live[0].id);render();if(!live.length)$('#catalogRows').textContent='Your catalog is ready. Published movies and series will appear here.';
 void refreshRecommendations();
 }catch(e){toast('Account connected, but catalog loading failed: '+e.message);}}
window.addEventListener('aether:session-ready',hydrateAccount);
window.addEventListener('aether:catalog-changed',hydrateAccount);
window.addEventListener('aether:session-cleared',()=>{layoutRequest++;serverLayout=null;cleanupMedia();catalog.splice(0,catalog.length,...previewCatalog);state={...raw,likes:raw.likes||[],saved:raw.saved||[],progress:raw.progress||{}};$('.hero').hidden=false;$('.featured-switcher').hidden=false;feature('signal');render();});

$('#profile').textContent='Checking account…';
void initializeAuth().finally(updateAccountLabel);
if(location.hash==='#account')accountRoute();
